arguments.command:
cd /app; rm -rf /tmp/c; mkdir -p /tmp/x; cp -r config /tmp/c; cp config-history/r0418/prev/profiles/edge.conf /tmp/c/profiles/edge.conf; cp config-history/r0419/prev/profiles/batch.conf /tmp/c/profiles/; cp config-history/r0419/prev/environments/prod-a.conf /tmp/c/environments/
cat > /tmp/r.py <<'E'
import os,sys
def res(svc,env,host,root):
    d={}
    def read(p,top):
        sec=None
        for l in open(p):
            l=l.strip()
            if not l or l[0]=='#':continue
            if l[0]=='[':sec=l.strip('[]');continue
            k,v=[x.strip() for x in l.split('=',1)]
            if k=='include':
                if sec is None:
                    q=os.path.join(os.path.dirname(p),v.replace('${env}',env).replace('${host}',host))
                    read(q,False)
                continue
            if top: d[k]=v
            else:
                if sec is None or sec==svc: d[k]=v
    read(f'/app/services/{svc}/service.conf',True)
    return d
if __name__=='__main__':
    for s in sorted(os.listdir('/app/services')):
        d=res(s,'prod-b','app-07',None)
        print(s,d.get('enabled'),int(d['port_base'])+int(d['port_offset']),d.get('admin_port'))
E
sed -i 's#/app/services/{svc}/service.conf#/tmp/s/{svc}/service.conf#' /tmp/r.py; cp -r services /tmp/s; python3 /tmp/r.py

